export interface ConfigOptions {
  vaultUrl?: string;
  cacheOptions?: CacheOptions;
}

export class KeyVaultConfig {
  private secretClient: SecretClient;
  private secretProvider: SecretProvider;
  private cachingProvider: CachingProvider;

  constructor(options: ConfigOptions = {}) {
    // Get vault URL from environment variable or options
    const vaultUrl =
      options.vaultUrl || process.env.AZURE_KEY_VAULT_URL || '';

    if (!vaultUrl) {
      throw new Error(
        'Key Vault URL must be provided via AZURE_KEY_VAULT_URL environment variable or options'
      );
    }

    // Use DefaultAzureCredential for managed identity authentication
    // This automatically uses managed identity when running in Azure
    const credential = new DefaultAzureCredential();

    // Initialize the SecretClient
    this.secretClient = new SecretClient(vaultUrl, credential);

    // Initialize providers
    this.secretProvider = new SecretProvider(this.secretClient);
    this.cachingProvider = new CachingProvider(
      this.secretProvider,
      options.cacheOptions
    );

    console.log(`Connected to Key Vault: ${vaultUrl}`);
    console.log('Using DefaultAzureCredential (managed identity)\n');
  }

  /**
   * Get the caching provider for configuration management
   */
  getProvider(): CachingProvider {
    return this.cachingProvider;
  }

  /**
   * Get the raw secret provider (bypasses cache)
   */
  getRawProvider(): SecretProvider {
    return this.secretProvider;
  }

  /**
   * Get the underlying SecretClient for advanced operations
   */
  getClient(): SecretClient {
    return this.secretClient;
  }
}
